script:
test("after 14:00 on Friday skips the weekend and a listed Monday holiday then counts 2 business days", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 2, holidays: ["2026-07-06"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-09" });
});

test("before cutoff on Wednesday with an empty holiday list and 1 transit day ships that day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-02" });
});

test("exactly 14:00 is not before the cutoff", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T14:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-02", deliveryDate: "2026-07-03" });
});

test("one minute before the cutoff on a business day still ships that day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T13:59", transitDays: 2, holidays: [] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-03" });
});

test("one minute after the cutoff ships the next business day and transit crosses the weekend", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T14:01", transitDays: 2, holidays: [] }), { shipDate: "2026-07-02", deliveryDate: "2026-07-06" });
});

test("transit days 0 makes delivery equal the delayed ship day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 0, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-06" });
});

test("Saturday and Sunday never ship and whole number forms 1 and 1.0 both count", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-04T09:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-07" });
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-05T13:59", transitDays: 1.0, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-07" });
});

test("a booking on a listed holiday ships the next business day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-06T10:00", transitDays: 1, holidays: ["2026-07-06"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-08" });
});

test("a holiday is honored in the first middle and last list slots", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-02T15:00", transitDays: 2, holidays: ["2026-07-03", "2026-07-06", "2026-07-07"] }), { shipDate: "2026-07-08", deliveryDate: "2026-07-10" });
});

test("leap day 2024-02-29 is a Thursday ship day and delivery crosses into March", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2024-02-29T13:59", transitDays: 2, holidays: [] }), { shipDate: "2024-02-29", deliveryDate: "2024-03-04" });
});

test("last day of December ships and delivery falls in the next year when January 1 is a holiday", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-12-31T10:00", transitDays: 2, holidays: ["2027-01-01"] }), { shipDate: "2026-12-31", deliveryDate: "2027-01-05" });
});

test("a holiday inside the transit count is honored when it is the middle list item", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-13T09:00", transitDays: 3, holidays: ["2026-01-01", "2026-07-15", "2026-12-25"] }), { shipDate: "2026-07-13", deliveryDate: "2026-07-17" });
});

test("late Friday with no holidays ships Monday not Tuesday", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 4, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-10" });
});

test("negative transit days throws invalid transitDays", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: -1, holidays: [] });
  }, /^invalid transitDays$/);
});

test("transit days that is not a whole number throws invalid transitDays", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 2.5, holidays: [] });
  }, /^invalid transitDays$/);
});

test("an input field other than bookedAt transitDays or holidays throws unknown field carrier", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [], carrier: "road" });
  }, /^unknown field: carrier$/);
});
